import numpy as np, itertools, collections
L=open('answer.xyz').read().split('\n'); n=int(L[0])
s=[];p=[]
for l in L[2:2+n]:
    q=l.split(); s.append(q[0]); p.append([float(x) for x in q[1:4]])
p=np.array(p)
cov={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'F':0.57,'P':1.07,'B':0.84,'Sn':1.39}
bonds=collections.defaultdict(list)
for i,j in itertools.combinations(range(n),2):
    d=np.linalg.norm(p[i]-p[j])
    if d < (cov[s[i]]+cov[s[j]])*1.3:
        bonds[i].append(j); bonds[j].append(i)
f=collections.Counter(s); print(dict(f))
for i in range(n):
    if s[i]!='H': print(i,s[i],len(bonds[i]),[(j,s[j]) for j in bonds[i]])
